// Q32_SetCompleteForPartyMember (A5Q2 Rescue on Mount Arreat) -- runs for each party member (via
// Q32_PropagateCompleteToParty / ExecuteFunctionForEveryPartyMember). If that member hasn't already
// Completed(0) or RewardAwaits(1) and is physically in Act V, marks the quest done for them: sets
// JustCompleted(0xd) + RewardAwaits(1), then records the survival tier as a step bit based on the quest's
// field_0xAC counter: 0xf->Step0x05 (all/most freed), 0xe->Step0x06, else->Step0x07 (fewest freed).
// This is how rescue credit (and the reward tier) propagates to nearby party members.
void __fastcall Q32_SetCompleteForPartyMember(::SGAMEDATA * pGame, D2UnitStrc * pUnit, void * pArg) {
    D2UnitDataPlayerStrc* pPlayerData = D2Common::Units::GetPlayerData(pUnit);
    D2BitBufferStrc* pBitBuffer = pPlayerData->pQuestRecord[pGame->nDifficulty];
    BOOL bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_RescueOnMountArreat, QUESTSTATE_Completed);
    if (bQuestState == 1) {
      return;
    }

    bQuestState = D2Common::QuestRecord::GetQuestState(pBitBuffer, QUEST_RescueOnMountArreat, QUESTSTATE_RewardAwaits);
    if (bQuestState == 1) {
      return;
    }

    D2RoomStrc* pRoom = D2Common::Units::UNITS_GetRoom(pUnit);
    if (!pRoom) {
      return;
    }

    eD2LevelId eLevelId = D2Common::DUNGEON::Dungeon::DRLGROOM_GetLevelIdFromRoom(pRoom);
    if (eLevelId == LEVEL_None) {
      return;
    }

    eAct eActNo = D2Common::Drlg::GetActNoFromLevelNumber(eLevelId);
    if (eActNo != ACT_V) {
      return;
    }

    /* SetQuestState(JustCompleted=0xd): mark self party member just-rescued the
                         barbarians */ D2Common::QuestRecord::SetQuestState(pBitBuffer, QUEST_RescueOnMountArreat, QUESTSTATE_JustCompleted);
    /* SetQuestState(RewardAwaits=1): party member may now claim reward from
                         Qual-Kehk */ D2Common::QuestRecord::SetQuestState(pBitBuffer, QUEST_RescueOnMountArreat, QUESTSTATE_RewardAwaits);
    D2QuestDataStrc* pQuestData = GetQuestDataByQuestNoInternal(pGame, QUESTINT_RescueOnMountArreat);
    int nSurvivalTier = pQuestData->pQuestSpecificData.pA5Q2->nPrisonersFreed;
    if (nSurvivalTier == 0xf) {
      /* SetQuestState(Step0x05): top survival tier (field_0xAC==0xf) -> best reward
                         tier */ D2Common::QuestRecord::SetQuestState(pBitBuffer, QUEST_RescueOnMountArreat, QUESTSTATE_Step0x05);
      return;
    }
    if (nSurvivalTier == 0xe) {
      /* SetQuestState(Step0x06): middle survival tier (field_0xAC==0xe) -> 2-item
                         reward tier */ D2Common::QuestRecord::SetQuestState(pBitBuffer, QUEST_RescueOnMountArreat, QUESTSTATE_Step0x06);
      return;
    }

    /* SetQuestState(Step0x07): lowest survival tier (fewest barbarians freed) ->
                         1-item reward tier */ D2Common::QuestRecord::SetQuestState(pBitBuffer, QUEST_RescueOnMountArreat, QUESTSTATE_Step0x07);
}

