    ::SGAMEDATA* pGame = pQuestData->pGame;
    pQuestData->sStateFunctions.fpQuestStateHandler[10] = Q32_Callback10_PlayerLeavesGame;
    pQuestData->sStateFunctions.fpQuestStateHandler[3] = Q32_Callback03_ChangedLevel;
    pQuestData->sStateFunctions.fpQuestStateHandler[8] = Q32_Callback08_MonsterKilled;
    pQuestData->sStateFunctions.fpQuestStateHandler[0] = Q32_Callback00_NpcActivate;
    pQuestData->sStateFunctions.fpQuestStateHandler[2] = Q32_Callback02_NpcDeactivate;
    pQuestData->sStateFunctions.fpQuestStateHandler[0xb] = Q32_Callback11_ScrollMessage;
    pQuestData->sStateFunctions.fpQuestStateHandler[0xd] = Q32_Callback13_PlayerStartedGame;
    pQuestData->sStateFunctions.fpQuestStateHandler[0xe] = Q32_Callback14_PlayerJoinedGame;
    pQuestData->pNpcMessages = A5Q2::aNpcGossipData;
    pQuestData->bIsActive = '\x01';
    pQuestData->nStateFlag = 0;
    D2QuestDataA5Q2Strc* pQuestSpecificData = D2_NEW_POOL_AT(pGame->pMemoryPool, D2QuestDataA5Q2Strc, "d:\\diablo2\\Diablo2\\Source\\D2Game/Quests/a5q2.cpp", 0x323);
    pQuestData->pQuestSpecificData.pA5Q2 = pQuestSpecificData;
    pQuestData->nQuestIdReal = QUEST_RescueOnMountArreat;
    pQuestData->fpStatusFilter = 0;
    pQuestData->nInitNo = 4;
    pQuestData->fpActiveFilter = Q32_ActiveFilter;
    pQuestData->fpSequenceFilter = Q32_SequenceFilter;
    pQuestData->nSequenceQuestId = QUEST_SpokeToMalachai;
